import java.util.*;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;
        int m = sc.nextInt();
        int n = sc.nextInt();
        int[] merged = new int[m + n];
        for (int i = 0; i < m; i++) merged[i] = sc.nextInt();
        for (int i = 0; i < n; i++) merged[m + i] = sc.nextInt();
        Arrays.sort(merged);
        int total = m + n;
        if (total % 2 == 1) {
            System.out.printf(Locale.US, "%.1f\n", (double)merged[total / 2]);
        } else {
            double med = (merged[total / 2 - 1] + merged[total / 2]) / 2.0;
            System.out.printf(Locale.US, "%.1f\n", med);
        }
    }
}

