#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

int merged[2005];

int main() {
    int m, n;
    if (scanf("%d %d", &m, &n) != 2) return 0;
    for (int i = 0; i < m; i++) scanf("%d", &merged[i]);
    for (int i = 0; i < n; i++) scanf("%d", &merged[m + i]);
    int total = m + n;
    qsort(merged, total, sizeof(int), cmp);
    if (total % 2 == 1) {
        printf("%.1f\n", (double)merged[total / 2]);
    } else {
        double med = (merged[total / 2 - 1] + merged[total / 2]) / 2.0;
        printf("%.1f\n", med);
    }
    return 0;
}
